Dam interaction effect
Same simple-slopes approach as the nutrient curvature figure, but for the two barrier variables against dist_mouth_m: the AME of each, with dist_mouth_m held fixed at its 10th/50th/90th percentile instead of averaged over sites. Richness didn’t have this built yet, so we compute it here too, reusing the same setup as the nutrient curvature section above.


Code
dist_mouth_levels_rich &lt;- quantile(river_model_data$dist_mouth_m, probs = c(0.1, 0.5, 0.9))
level_labels &lt;- c("low", "median", "high")

rows &lt;- list()
for (pair_idx in seq_along(rich_inter_pairs)) {
  var &lt;- rich_inter_pairs[[pair_idx]][1]
  for (lvl_idx in seq_along(dist_mouth_levels_rich)) {
    lvl &lt;- dist_mouth_levels_rich[lvl_idx]
    draws &lt;- sapply(rd_list, \(rd) {
      X_plus &lt;- X_rich; X_plus[, var] &lt;- X_plus[, var] + 0.02
      X_plus[, "dist_mouth_m"] &lt;- lvl
      X_minus &lt;- X_rich; X_minus[, var] &lt;- X_minus[, var] - 0.02
      X_minus[, "dist_mouth_m"] &lt;- lvl
      mean((predicted_rich(X_plus, rd) - predicted_rich(X_minus, rd)) / (2 * 0.02))
    })
    rows[[length(rows) + 1]] &lt;- tibble(
      var = var, level = level_labels[lvl_idx],
      mean = mean(draws),
      `0.025quant` = quantile(draws, 0.025),
      `0.975quant` = quantile(draws, 0.975)
    )
  }
}
dam_interaction_rich &lt;- bind_rows(rows) |&gt;
  mutate(level = factor(level, levels = level_labels))




